SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_144189aee4ead547>
    <urn:graphragprov:unit:u_69ac7c14e36e7d3c>
    <urn:graphragprov:unit:u_9507f474d00735cb>
    <urn:graphragprov:unit:u_9a1a0b0279fc286c>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
